// Interface generated by Atlas. It reads the data model from /api/_schema
// and builds a tab, a form and a table for each collection.
"use strict";

const WORDS = {
  en: { add: "Add", save: "Save", cancel: "Cancel", edit: "Edit", remove: "Delete", search: "Search", empty: "No records yet.", saved: "Saved.", removed: "Deleted.", confirm: "Delete this record?", yes: "Yes", no: "No", summary: "Summary", count: "Records", total: "Total", failed: "Could not save:", loadFailed: "Could not load the data." },
  tr: { add: "Ekle", save: "Kaydet", cancel: "Vazgeç", edit: "Düzenle", remove: "Sil", search: "Ara", empty: "Henüz kayıt yok.", saved: "Kaydedildi.", removed: "Silindi.", confirm: "Bu kayıt silinsin mi?", yes: "Evet", no: "Hayır", summary: "Özet", count: "Kayıt", total: "Toplam", failed: "Kaydedilemedi:", loadFailed: "Veriler yüklenemedi." },
  de: { add: "Hinzufügen", save: "Speichern", cancel: "Abbrechen", edit: "Bearbeiten", remove: "Löschen", search: "Suchen", empty: "Noch keine Einträge.", saved: "Gespeichert.", removed: "Gelöscht.", confirm: "Diesen Eintrag löschen?", yes: "Ja", no: "Nein", summary: "Übersicht", count: "Einträge", total: "Summe", failed: "Speichern fehlgeschlagen:", loadFailed: "Daten konnten nicht geladen werden." },
  fr: { add: "Ajouter", save: "Enregistrer", cancel: "Annuler", edit: "Modifier", remove: "Supprimer", search: "Rechercher", empty: "Aucun enregistrement.", saved: "Enregistré.", removed: "Supprimé.", confirm: "Supprimer cet enregistrement ?", yes: "Oui", no: "Non", summary: "Résumé", count: "Enregistrements", total: "Total", failed: "Échec de l'enregistrement :", loadFailed: "Impossible de charger les données." },
  it: { add: "Aggiungi", save: "Salva", cancel: "Annulla", edit: "Modifica", remove: "Elimina", search: "Cerca", empty: "Nessun record.", saved: "Salvato.", removed: "Eliminato.", confirm: "Eliminare questo record?", yes: "Sì", no: "No", summary: "Riepilogo", count: "Record", total: "Totale", failed: "Salvataggio non riuscito:", loadFailed: "Impossibile caricare i dati." },
  ar: { add: "إضافة", save: "حفظ", cancel: "إلغاء", edit: "تعديل", remove: "حذف", search: "بحث", empty: "لا توجد سجلات بعد.", saved: "تم الحفظ.", removed: "تم الحذف.", confirm: "حذف هذا السجل؟", yes: "نعم", no: "لا", summary: "ملخص", count: "السجلات", total: "المجموع", failed: "تعذر الحفظ:", loadFailed: "تعذر تحميل البيانات." },
};

let schema = null;
let t = WORDS.en;
let current = null;
let editing = null;

const $ = (sel) => document.querySelector(sel);

function el(tag, attrs = {}, ...children) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === "class") node.className = v;
    else if (k.startsWith("on")) node.addEventListener(k.slice(2), v);
    else if (v !== false && v !== null && v !== undefined) node.setAttribute(k, v === true ? "" : v);
  }
  for (const c of children.flat()) {
    if (c !== null && c !== undefined) node.append(c instanceof Node ? c : document.createTextNode(String(c)));
  }
  return node;
}

async function api(method, path, body) {
  const res = await fetch(path, {
    method,
    headers: body ? { "Content-Type": "application/json" } : {},
    body: body ? JSON.stringify(body) : undefined,
  });
  if (res.status === 204) return null;
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    const err = new Error(data.error || res.statusText);
    err.field = data.field;
    throw err;
  }
  return data;
}

function notice(text, bad) {
  const box = $("#notice");
  box.textContent = text;
  box.className = bad ? "notice bad" : "notice";
  box.hidden = !text;
}

function inputFor(field, value) {
  const id = "f-" + field.name;
  const common = { id, name: field.name, required: !!field.required };
  let input;
  switch (field.type) {
    case "longtext":
      input = el("textarea", { ...common, rows: 3 });
      input.value = value ?? "";
      break;
    case "integer":
      input = el("input", { ...common, type: "number", step: "1" });
      input.value = value ?? "";
      break;
    case "number":
      input = el("input", { ...common, type: "number", step: "any" });
      input.value = value ?? "";
      break;
    case "date":
      input = el("input", { ...common, type: "date" });
      input.value = value ?? "";
      break;
    case "boolean":
      input = el("input", { id, name: field.name, type: "checkbox" });
      input.checked = !!value;
      break;
    case "choice":
      input = el("select", common, el("option", { value: "" }, "—"), field.choices.map((c) => el("option", { value: c }, c)));
      input.value = value ?? "";
      break;
    default:
      input = el("input", { ...common, type: "text", maxlength: 200 });
      input.value = value ?? "";
  }
  const label = el("label", { for: id }, field.label + (field.required ? " *" : ""));
  return el("div", { class: field.type === "boolean" ? "field check" : "field" }, label, input);
}

function readForm(form, entity) {
  const out = {};
  for (const f of entity.fields) {
    const input = form.elements[f.name];
    if (f.type === "boolean") out[f.name] = input.checked;
    else if ((f.type === "integer" || f.type === "number") && input.value !== "") out[f.name] = Number(input.value);
    else out[f.name] = input.value;
  }
  return out;
}

function renderForm(entity, record) {
  const form = el("form", { class: "card", id: "record-form", novalidate: true });
  form.append(...entity.fields.map((f) => inputFor(f, record ? record[f.name] : undefined)));
  const actions = el("div", { class: "actions" }, el("button", { type: "submit", class: "primary" }, record ? t.save : t.add));
  if (record) actions.append(el("button", { type: "button", onclick: () => { editing = null; show(entity.name); } }, t.cancel));
  form.append(actions);
  form.addEventListener("submit", async (ev) => {
    ev.preventDefault();
    try {
      if (record) await api("PUT", `/api/${entity.name}/${record.id}`, readForm(form, entity));
      else await api("POST", `/api/${entity.name}`, readForm(form, entity));
      editing = null;
      notice(t.saved);
      await show(entity.name);
    } catch (err) {
      const field = entity.fields.find((f) => f.name === err.field);
      notice(`${t.failed} ${field ? field.label + ": " : ""}${err.message}`, true);
    }
  });
  return form;
}

function cell(field, value) {
  if (value === null || value === undefined || value === "") return "";
  if (field.type === "boolean") return value ? "✓" : "✗";
  return String(value);
}

async function renderTable(entity, query) {
  const data = await api("GET", `/api/${entity.name}` + (query ? `?q=${encodeURIComponent(query)}` : ""));
  if (!data.items.length) return el("p", { class: "empty" }, t.empty);
  const head = el("tr", {}, entity.fields.map((f) => el("th", { scope: "col" }, f.label)), el("th", { scope: "col" }, ""));
  const rows = data.items.map((item) =>
    el("tr", { "data-id": item.id },
      entity.fields.map((f) => el("td", {}, cell(f, item[f.name]))),
      el("td", { class: "row-actions" },
        el("button", { type: "button", onclick: () => { editing = item; show(entity.name); } }, t.edit),
        el("button", { type: "button", class: "danger", onclick: async () => {
          if (!confirm(t.confirm)) return;
          await api("DELETE", `/api/${entity.name}/${item.id}`);
          notice(t.removed);
          await show(entity.name);
        } }, t.remove))));
  return el("div", { class: "table-wrap" }, el("table", {}, el("thead", {}, head), el("tbody", {}, rows)));
}

async function renderSummary() {
  const data = await api("GET", "/api/_summary");
  const cards = schema.entities.map((e) => {
    const s = data[e.name] || { count: 0, totals: {} };
    const totals = Object.entries(s.totals).map(([k, v]) => {
      const f = e.fields.find((x) => x.name === k);
      return el("div", { class: "metric" }, el("span", {}, `${t.total} · ${f ? f.label : k}`), el("strong", {}, Number(v).toLocaleString()));
    });
    return el("section", { class: "card" }, el("h2", {}, e.label), el("div", { class: "metric" }, el("span", {}, t.count), el("strong", {}, s.count)), totals);
  });
  return el("div", { class: "summary" }, cards);
}

async function show(name) {
  current = name;
  for (const b of document.querySelectorAll("nav button")) b.setAttribute("aria-current", b.dataset.name === name ? "page" : "false");
  const main = $("#content");
  main.replaceChildren();
  try {
    if (name === "_summary") {
      main.append(await renderSummary());
      return;
    }
    const entity = schema.entities.find((e) => e.name === name);
    const search = el("input", { type: "search", placeholder: t.search, "aria-label": t.search, id: "search" });
    const tableBox = el("div", { id: "table" });
    search.addEventListener("input", async () => tableBox.replaceChildren(await renderTable(entity, search.value)));
    main.append(el("h2", {}, entity.label), renderForm(entity, editing), search, tableBox);
    tableBox.append(await renderTable(entity, ""));
  } catch (err) {
    notice(t.loadFailed + " " + err.message, true);
  }
}

async function start() {
  schema = await api("GET", "/api/_schema");
  t = WORDS[schema.language] || WORDS.en;
  document.documentElement.lang = schema.language || "en";
  if (schema.language === "ar") document.documentElement.dir = "rtl";
  document.title = schema.name;
  $("#title").textContent = schema.name;
  $("#subtitle").textContent = schema.description || "";
  const nav = $("nav");
  for (const e of schema.entities) nav.append(el("button", { type: "button", "data-name": e.name, onclick: () => { editing = null; notice(""); show(e.name); } }, e.label));
  nav.append(el("button", { type: "button", "data-name": "_summary", onclick: () => { notice(""); show("_summary"); } }, t.summary));
  await show(schema.entities[0].name);
}

start().catch((err) => notice("Could not start: " + err.message, true));
